entries.content:
{
  "world_history": {
    "timeline": [
      {
        "time": "距今约5000年",
        "name": "大寂灭",
        "effect": "世界失去了所有神性存在，残留的法则碎片化为魔力，散布在万物之中。"
      },
      {
        "time": "距今约3000年",
        "name": "百族血战",
        "effect": "失去神明指引的各大种族为争夺生存空间相互攻伐，雇佣兵与怪物猎人开始联合，形成了冒险者公会的雏形。"
      },
      {
        "time": "距今约1500年",
        "name": "古哥布林帝国的崩溃",
        "effect": "曾通过吸收异族血脉来进化的古哥布林帝国因内部血脉污染而覆灭，幸存的哥布林退化为原始的部落形态。"
      },
      {
        "time": "距今约1200年",
        "name": "人类崛起",
        "effect": "掌握了铁器与秩序的人类王国迅速扩张，并将所有非人种族定义为必须清除的“怪物”。"
      },
      {
        "time": "距今约800年",
        "name": "圣教确立",
        "effect": "人类王国将对“人性”与“秩序”的推崇凝聚为国教，进一步固化了对所有异族的系统性排斥与敌视。"
      },
      {
        "time": "距今约100年",
        "name": "开拓时代",
        "effect": "人类王国的领土扩张达到极限，开始委托冒险者公会清理边境地区的“怪物巢穴”，为新的定居点扫清障碍。"
      }
    ]
  }
}

