entries.content:
{
  "name": "阿基坦人类王国",
  "parent_realm": "位于大陆中央最丰饶的平原地区",
  "summary": "一个以圣教为国教，奉行人类至上与绝对秩序的中央集权王国。在“开拓时代”的国策下，整个国家呈现出一种积极向外扩张，同时对内严格管制的社会氛围。国民普遍对异族抱有强烈的排斥与警惕。",
  "figures": [
    {
      "name": "莉雅·冯·阿基坦",
      "summary": "王国的第三王女，也是圣教的见习圣女。因其美貌和与生俱来的微弱圣光亲和力而闻名，被誉为“王国之花”，常在王都的庆典中公开露面，是民众的精神象征。"
    },
    {
      "name": "艾琳·克伦威尔",
      "summary": "王国骑士团“狮鹫之心”的年轻分队长。出身平民，凭借卓越的剑技与对王国的绝对忠诚获得晋升。性格坚毅正直，主要负责王都周边的治安巡逻。"
    }
  ],
  "locations": [
    {
      "name": "白塔城",
      "summary": "阿基坦王国的王都，以其中心矗立的白色巨塔而得名。是大陆的政治、文化与宗教中心，城墙高耸，街道规划井然有序，商业繁荣。",
      "layout": "坐落于王国的正中心，被广阔的农田和数个卫星城镇环绕。"
    },
    {
      "name": "格莱姆斯要塞",
      "summary": "王国东部边境的军事重镇，为防御荒野中的“怪物”和向东开拓领土而修建。城墙由黑色的巨石构成，常年驻扎着王国的精锐部队。",
      "layout": "位于王国东境的山脉隘口处，是进入东部荒野的唯一通道。"
    }
  ]
}

