entries.content:
{
  "name": "铁砧堡王国",
  "parent_realm": "位于大陆北方的龙脊山脉深处",
  "summary": "一个孤立且保守的矮人山中王国。这里的矮人是杰出的矿工与铁匠，社会围绕着氏族与工坊展开。他们对地表事务漠不关心，一心沉醉于对金属和宝石的无尽探求中，鲜少与外族往来。",
  "figures": [],
  "locations": [
    {
      "name": "地心熔炉",
      "summary": "铁砧堡的首都与心脏，环绕着一座巨大的地脉熔岩井而建。城中终日回响着锻打的锤声，空气里弥漫着煤灰与金属的气味。",
      "layout": "位于龙脊山脉主峰的正下方，通过复杂的隧道网络与其他矿区相连。"
    }
  ]
}

