entries.content:
{
  "name": "翡翠森林",
  "parent_realm": "位于大陆西南部，与人类王国隔着广阔的沼泽地带",
  "summary": "一片被古老魔法守护的广袤森林，是精灵族的最后家园。这里的精灵社会以自然循环为核心，尊崇知识与和谐。由于人类的无尽扩张，他们选择自我封闭，对外界抱持着深刻的不信任与警惕。",
  "figures": [
    {
      "name": "希尔维娅",
      "summary": "翡翠森林的首席祭司与守护者，负责主持祭祀并维系森林的防御结界。年龄虽轻，但因其强大的魔力天赋和对古老知识的掌握而备受尊敬。她肩负着保护族人的重任，对任何入侵者都毫不留情。"
    },
    {
      "name": "露娜",
      "summary": "一名年轻的精灵游侠，负责在森林外围巡逻，监视人类与怪物的动向。性格好奇且好动，对森林外的世界抱有幻想，但被族规严格约束着。"
    }
  ],
  "locations": [
    {
      "name": "巨树之庭",
      "summary": "精灵的首都，建造在数棵巨大的活体古树之上，通过藤蔓与木质的桥梁相连。是精灵议会和祭司院的所在地。",
      "layout": "位于翡翠森林的最中心，被多层魔法结界所保护。"
    },
    {
      "name": "月光圣泉",
      "summary": "一处蕴含着精纯魔力的泉水，是维持森林生机与结界能量的源泉。只有祭司和被选中的精灵才能靠近。",
      "layout": "隐藏在巨树之庭下方一处隐秘的洞窟内。"
    }
  ]
}

