entries.content:
{
  "name": "东境荒原",
  "parent_realm": "位于大陆东部，与阿基坦人类王国的格莱姆斯要塞隔着破碎山脊相望",
  "summary": "一片广阔而贫瘠的混乱地带，这里没有统一的政权，而是由数个强大的魔族领主割据。力量是此地唯一的法则，弱肉强食的丛林法则在这里体现得淋漓尽致。各个魔族部落与城邦之间征伐不断，充满了背叛、欲望与机遇。",
  "figures": [
    {
      "name": "莉莉丝",
      "summary": "统治着“欢愉城堡”的魅魔领主。她以美貌和操纵人心的魔法而闻名，通过吸收他人的精气来维持强大的力量。在残酷的东境荒原中，她依靠狡猾的手段和绝对的实力占据了一席之地。"
    },
    {
      "name": "艾拉",
      "summary": "莉莉丝的贴身侍女与护卫，是一个沉默寡言的翼人族。她拥有极快的速度与战斗技巧，对莉莉丝绝对忠诚，是执行暗杀与护卫任务的利刃。"
    }
  ],
  "locations": [
    {
      "name": "堕落之都·阿斯莫德",
      "summary": "东境荒原中最大也最混乱的魔族城市，建立在一座枯竭的火山之上。这里是贸易、阴谋和罪恶的聚集地，任何东西都可以被交易。",
      "layout": "位于东境荒原的中心地带，是各方魔族势力交汇的枢纽。"
    },
    {
      "name": "欢愉城堡",
      "summary": "莉莉丝的私人城堡，以其奢华的装饰和无处不在的魅惑魔法而著称。是堕落之都内一座独立的城中之城。",
      "layout": "坐落在堕落之都的最高处，俯瞰着整座城市的混乱景象。"
    }
  ]
}

