{
  "racial_templates": [
    {
      "race": "人类",
      "summary": "适应性最强的种族，没有突出的天赋，但胜在均衡。他们构成了大陆上数量最庞大的文明群体。",
      "attributes": {
        "average_lifespan": "50-80年",
        "average_height_male": "170cm",
        "average_height_female": "160cm",
        "physical_traits": [
          "发色与瞳色多样，以黑、棕、金、蓝为主",
          "体能与魔力亲和度个体差异极大，但平均水平中等",
          "没有天生的物理或魔法抗性"
        ]
      }
    },
    {
      "race": "精灵",
      "summary": "与自然共生的长寿种族，拥有优雅的外表和较高的魔力亲和力，但身体较为纤弱，繁育能力较低。",
      "attributes": {
        "average_lifespan": "500-700年",
        "average_height_male": "175cm",
        "average_height_female": "165cm",
        "physical_traits": [
          "特征性的尖长耳朵",
          "发色多为金色、银色或绿色，瞳色多为蓝色或绿色",
          "天生对自然系魔力有90%以上的高亲和度",
          "身体力量普遍较弱，肌肉密度低于人类约15%"
        ]
      }
    },
    {
      "race": "矮人",
      "summary": "生活在地下的强健种族，是天生的工匠和战士，但对魔法普遍不敏感。",
      "attributes": {
        "average_lifespan": "200-250年",
        "average_height_male": "140cm",
        "average_height_female": "135cm",
        "physical_traits": [
          "身材敦实，骨骼和肌肉密度比人类高出约30%",
          "拥有出色的黑暗视觉能力",
          "对各类毒素和物理冲击有较高的天生抗性",
          "95%以上的个体对魔力感知迟钝"
        ]
      }
    },
    {
      "race": "魔族（魅魔亚种）",
      "summary": "源自混乱魔力区域的类人种族，通过吸收生命精气来维持自身存在和力量。外表极具吸引力，是其捕食的伪装。",
      "attributes": {
        "average_lifespan": "依赖精气补给，理论上可达数百年",
        "average_height_male": "180cm",
        "average_height_female": "160cm",
        "physical_traits": [
          "背后生有小巧的恶魔翅膀，脑后或头侧有小巧的弯角，通常作为装饰",
          "瞳孔形状多为心形或菱形，瞳色呈宝石般的红色或紫色",
          "皮肤会散发一种微量的、可影响心智的麝香信息素",
          "声线频率天生处于最能引起其他类人生物好感的波段内"
        ]
      }
    }
  ]
}

entries.content:
{
  "power_system": {
    "name": "战力指数",
    "attributes": [
      {
        "name": "生命",
        "description": "影响生物的生命力与寿命。数值越高，越难被杀死，存活时间越长。"
      },
      {
        "name": "体质",
        "description": "影响生物的物理能力，包括力量、防御和速度。数值越高，肉体战斗力越强。"
      },
      {
        "name": "魔力",
        "description": "影响生物施展魔法的能力。数值越高，魔法效果越强，同时也会延长寿命。"
      },
      {
        "name": "智力",
        "description": "影响生物的思考与学习能力。数值越高，理智越稳定，对魔力的增幅效果也越强。"
      }
    ],
    "calculation_formula": "战力 = (生命 / 2) + 体质 + 魔力 + 智力",
    "rule": "在一对一的战斗中，战斗结果由双方的战力指数高低直接决定。",
    "base_stats": {
      "human": {
        "生命": 70,
        "体质": 20,
        "魔力": 10,
        "智力": 40
      },
      "elf": {
        "生命": 200,
        "体质": 25,
        "魔力": 30,
        "智力": 30
      },
      "demon": {
        "生命": 100,
        "体质": 40,
        "魔力": 10,
        "智力": 30
      },
      "dwarf": {
        "生命": 150,
        "体质": 50,
        "魔力": 0,
        "智力": 25
      },
      "goblin": {
        "生命": 50,
        "体质": 10,
        "魔力": 5,
        "智力": 5
      }
    },
    "growth_mechanic": "所有属性都可以通过锻炼、学习、战斗或使用特殊道具等方式得到提升。"
  }
}

