entries.content:
{
  "goblin_evolution_chain": {
    "base_form": {
      "name": "哥布林",
      "summary": "哥布林族群的基础单位。个体弱小，智力低下，依靠数量优势进行狩猎和战斗。是巢穴运作的基石，十天就能从刚出生成熟。",
      "evolution_source": "基础形态，无需特殊血脉。",
      "attributes": {
        "lifespan": "3-5年",
        "height": "90cm - 120cm",
        "physical_traits": ["皮肤呈绿色或棕色，嗅觉灵敏，拥有夜视能力。"],
        "base_stats": {
          "生命": 50,
          "体质": 10,
          "魔力": 5,
          "智力": 5
        },
        "combat_power": 45
      }
    },
    "advanced_forms": [
      {
        "name": "大哥布林",
        "summary": "通过吸收强壮种族的血脉而诞生的亚种。它们是天生的肉盾和劳工，凭借巨大的体型和力量在战场上冲锋陷阵，或在巢穴中承担重体力劳动。",
        "evolution_source": "主要来自吸收了人类、矮人等高体质种族的血脉。",
        "attributes": {
          "lifespan": "5-8年",
          "height": "180cm - 210cm",
          "physical_traits": ["身材魁梧，肌肉发达，拥有远超普通哥布林的力量。肉棒长度在16-20cm之间，更为粗壮。"],
          "base_stats": {
            "生命": 150,
            "体质": 40,
            "魔力": 0,
            "智力": 15
          },
          "combat_power": 130
        }
      },
      {
        "name": "哥布林战士",
        "summary": "吸收了擅长战斗的种族血脉后诞生的精英单位。它们比普通哥布林更聪明，掌握了基础的战斗技巧，是族群的中坚力量。",
        "evolution_source": "主要来自吸收了人类士兵、精灵游侠等具备战斗经验的种族血脉。",
        "attributes": {
          "lifespan": "10-15年",
          "height": "160cm - 190cm",
          "physical_traits": ["体格精悍，反应速度快，懂得使用多种武器并进行小队协同作战。"],
          "base_stats": {
            "生命": 150,
            "体质": 50,
            "魔力": 10,
            "智力": 30
          },
          "combat_power": 165
        }
      },
      {
        "name": "哥布林萨满",
        "summary": "吸收了高魔力种族的血脉后诞生的施法者。它们是族群的智囊和辅助者，能使用原始的邪恶魔法来削弱敌人或强化同伴。",
        "evolution_source": "主要来自吸收了精灵、魅魔等高魔力种族的血脉。",
        "attributes": {
          "lifespan": "20-30年",
          "height": "120cm - 150cm",
          "physical_traits": ["身体相对孱弱，但大脑更为发达，能够感知并引导魔力。"],
          "base_stats": {
            "生命": 120,
            "体质": 20,
            "魔力": 80,
            "智力": 50
          },
          "combat_power": 210
        }
      },
      {
        "name": "哥布林英雄",
        "summary": "集多种优良血脉于一身，在残酷的内部竞争中胜出的万中无一的王者。它们是族群意志的化身，兼具强大的力量、狡猾的智慧和施法能力，是天生的领袖。",
        "evolution_source": "吸收了多种高质量血脉（如王族、圣女、英雄等）后，在极小概率下发生的奇迹突变。",
        "attributes": {
          "lifespan": "80-120年",
          "height": "180cm - 300cm",
          "physical_traits": ["体型可怖，几乎集成了所有亚种的优点，能够熟练运用魔法和物理战斗技巧。"],
          "base_stats": {
            "生命": 800,
            "体质": 200,
            "魔力": 200,
            "智力": 150
          },
          "combat_power": 950
        }
      }
    ]
  }
}

