entries.content:
{
  "female_grading_system": {
    "name": "雌性等级",
    "description": "根据雌性个体天生的血脉天赋与后天习得的能力进行综合评定，直接决定其对哥布林族群的繁殖价值。等级分为C、B、A、S四个级别。",
    "grading_rules": [
      {
        "grade": "C",
        "summary": "普通雌性。血脉中不具备显著的特殊天赋，只能作为基础的繁殖单位。",
        "reproduction_output": {
          "quantity_per_birth": "5-10",
          "offspring_details": [
            "100% 概率产出 哥布林",
            "5% 概率额外产出 1名 大哥布林"
          ]
        },
        "inheritance_rule": "无法继承天赋。"
      },
      {
        "grade": "B",
        "summary": "优良雌性。血脉中具备某项较为有用的天赋（如：较高的体质、基础的元素亲和），有一定的培养价值。",
        "reproduction_output": {
          "quantity_per_birth": "8-12",
          "offspring_details": [
            "100% 概率产出 哥布林",
            "20% 概率额外产出 1名 大哥布林",
            "5% 概率额外产出 1名 哥布林战士"
          ]
        },
        "inheritance_rule": "后代有30%概率继承其一项天赋。"
      },
      {
        "grade": "A",
        "summary": "稀有雌性。血脉中具备某项强大的天赋（如：王族血统、高阶魔法才能），是族群进化的关键。",
        "reproduction_output": {
          "quantity_per_birth": "10-15",
          "offspring_details": [
            "100% 概率产出 1名 大哥布林",
            "20% 概率额外产出 1名 哥布林战士 或 哥布林萨满"
          ]
        },
        "inheritance_rule": "后代有50%概率继承其一项强力天赋。"
      },
      {
        "grade": "S",
        "summary": "传说雌性。血脉中具备足以改变战局的顶级天赋（如：圣女的圣光之力、英雄的勇气光环），是诞生王者的基石。",
        "reproduction_output": {
          "quantity_per_birth": "12-20",
          "offspring_details": [
            "100% 概率产出 1-2名 哥布林战士 或 哥布林萨满",
            "5% 概率额外产出 1名 哥布林英雄"
          ]
        },
        "inheritance_rule": "后代100%稳定继承其一项极强天赋。"
      }
    ],
    "additional_note": "雌性等级通常会影响其容貌、身材与社会地位，但并非绝对。一个出身平凡的C级平民也可能拥有不输于贵族的容貌。"
  }
}

