  "defense_system": {
    "name": "巢穴防守",
    "summary": "巢穴会不定期遭遇来自外部势力的攻击。攻击的强度与巢穴的“知名度”直接相关。成功抵御攻击可以获得奖励，失败则意味着游戏结束。",
    "core_mechanic": {
      "name": "知名度",
      "description": "衡量哥布林巢穴在外界威胁程度的数值。通过掠夺、战斗等行为提升。知名度越高，吸引来的敌人越强大，也越频繁。",
      "levels": [
        {
          "level": 1,
          "name": "流言蜚语",
          "threshold": "0-99",
          "description": "只有零星的目击者。传闻被当作乡野怪谈，不被采信。",
          "invaders": "1-2名本地猎人或迷路的旅人。",
          "total_combat_power": "约 150-300"
        },
        {
          "level": 2,
          "name": "邻近警报",
          "threshold": "100-299",
          "description": "附近的村庄开始认真对待威胁，并组织了民兵。",
          "invaders": "一支由4-6名人类村民组成的民兵队。",
          "total_combat_power": "约 300-500"
        },
        {
          "level": 3,
          "name": "区域威胁",
          "threshold": "300-599",
          "description": "周边的小镇开始恐慌，并在冒险者公会发布了清剿委托。",
          "invaders": "一支由3-4名C级冒险者组成的小队。",
          "total_combat_power": "约 800-1200"
        },
        {
          "level": 4,
          "name": "领主关注",
          "threshold": "600-999",
          "description": "地方领主注意到了威胁，派遣了正规军。更强大的冒险者也被吸引而来。",
          "invaders": "一支由10-15名王国骑士组成的巡逻队，或一支B级冒险者小队。",
          "total_combat_power": "约 2000-3500"
        },
        {
          "level": 5,
          "name": "王国通缉",
          "threshold": "1000-1999",
          "description": "巢穴的威胁被上报至王都，成为国家层面的清剿目标。",
          "invaders": "由“艾琳·克伦威尔”或同级别骑士长率领的50人规模的王国军队，伴有A级冒险者。",
          "total_combat_power": "约 8000-15000"
        },
        {
          "level": 6,
          "name": "世界公敌",
          "threshold": "2000+",
          "description": "哥布林的威胁震惊了所有种族，人类、精灵等势力开始联合，准备发动总攻。",
          "invaders": "由人类、精灵等种族组成的联合大军。",
          "total_combat_power": "超过 30000"
        }
      ]
    },
    "rewards": {
      "name": "防守战利品",
      "description": "成功击退或歼灭入侵者后获得的物品。",
      "types": [
        {
          "name": "礼物",
          "source": "从特定身份的敌人身上获得，如冒险者的饰品、商人的货物等。",
          "usage": "可赠送给巢穴中的雌性，用以提升她们的好感度与理性值。",
          "examples": [
            "一件漂亮的衣物（来自人类冒险者）",
            "一小个美味的奶油蛋糕（来自人类商人）",
            "一本描绘王都风光的画册（来自贵族护卫）"
          ]
        },
        {
          "name": "特殊物品",
          "source": "从强大的敌人或其装备上分解获得的核心部件。",
          "usage": "用于研发科技、建造高级设施或锻造强力武器。",
e         "format": "获得 特殊物品 10"
        },
        {
          "name": "材料",
          "source": "敌人携带的基础物资或从其尸体上搜刮而来。",
          "usage": "用于日常的设施建造、陷阱制作和物品生产。",
          "format": "获得 材料 50"
        }
      ]
    },
    "technology_note": "特殊物品与材料的具体用途，将通过后续的科技研发系统解锁。"
  }
}

