entries.content:
{
  "technology_system": {
    "name": "巢穴科技",
    "summary": "通过消耗资源与时间进行研究，解锁新的建筑、装备和能力，是哥布林族群从原始走向强大的核心系统。",
    "unlock_methods": [
      {
        "method": "常规研究",
        "description": "消耗“材料”和“特殊物品”，在指定设施中进行研究。"
      },
      {
        "method": "图纸解析",
        "description": "从特定敌人身上缴获“研究图纸”后，可支付少量资源直接解锁对应科技，但需满足前置科技要求。"
      },
      {
        "method": "雌性指导",
        "description": "在“女性恶堕魔法”研究完成后，拥有专门知识的恶堕雌性可被说服，直接指导并解锁特定科技。同样需要满足前置科技，且每个雌性一生最多指导两次。"
      }
    ],
    "tree": [
      {
        "tier": 1,
        "name": "石器时代",
        "summary": "利用石头和木材等基础材料，满足巢穴最基本的生存与扩张需求。",
        "technologies": [
          {
            "name": "石器装备库",
            "cost": {
              "材料": 20
            },
            "time_days": 10,
            "effect": "解锁所有基础石制武器和工具的制作权限。"
          },
          {
            "name": "石制牢房",
            "cost": {
              "材料": 20
            },
            "time_days": 10,
            "effect": "允许建造石制牢房，可关押最多3名雌性俘虏。"
          },
          {
            "name": "血肉祭台",
            "cost": {
              "材料": 50
            },
            "time_days": 20,
            "effect": "允许建造祭台。每献祭10名哥布林，所有现存哥布林的“生命”+5或“体质”+1（随机生效）。哥布林会主动接受献祭。"
          },
          {
            "name": "落石陷阱",
            "cost": {
              "材料": 10
            },
            "time_days": 10,
            "effect": "允许在巢穴入口处布置陷阱，可对入侵的敌人造成固定的战力削减（-20）。"
          }
        ]
      },
      {
        "tier": 2,
        "name": "部族武装",
        "summary": "对哥布林进行初步武装和训练，提升族群的整体战斗能力。",
        "technologies": [
          {
            "name": "长矛战术",
            "prerequisite": "石器装备库",
            "cost": {
              "材料": 40
            },
            "time_days": 15,
            "effect": "为所有哥布林装备石制长矛，群体战力额外增加30。"
          },
          {
            "name": "简易护具",
            "prerequisite": "石器装备库",
            "cost": {
              "材料": 40
            },
            "time_days": 15,
            "effect": "为所有哥布林装备木质与皮革护甲，群体战力额外增加30。"
          },
          {
            "name": "投掷技巧",
            "prerequisite": "石器装备库",
            "cost": {
              "材料": 50
            },
            "time_days": 20,
            "effect": "训练哥布林投掷石块的技巧，群体战力额外增加20。"
          },
          {
            "name": "牢房扩建",
            "prerequisite": "石制牢房",
            "cost": {
              "材料": 40,
              "特殊物品": 1
            },
            "time_days": 30,
            "effect": "升级所有牢房，使巢穴总计可关押的雌性上限提升至10名。"
          },
          {
            "name": "格斗训练场",
            "prerequisite": "长矛战术",
            "cost": {
              "材料": 60,
              "特殊物品": 5
            },
            "time_days": 40,
            "effect": "允许建造训练场，使所有哥布林的基础战力永久提升10。"
          }
        ]
      }
    ]
  }
}

