  "technology_tree_branch": {
    "branch_name": "魔法奥秘",
    "summary": "一条独立的科技分支，专注于研究和掌握魔法的力量。该分支的研究完全依赖于哥布林萨满的存在与数量。",
    "unlock_condition": "巢穴中必须至少存在1名哥布林萨满。",
    "technologies": [
      {
        "tier": 1,
        "name": "哥布林低级魔法",
        "requirement": "至少1名哥布林萨满",
        "base_research_time_days": 10,
        "acceleration_rule": "每额外增加1名哥布林萨满，研究时间减少5天（最低至1天）。",
        "cost": {
          "材料": 100,
          "特殊物品": 5
        },
        "effect": "解锁低级魔法的施放权限，如‘照明’、‘火球’、‘水球’、‘沼泽术’。为族群提供基础的魔法支援与战斗能力。"
      },
      {
        "tier": 2,
        "name": "哥布林中级魔法",
        "prerequisite": "哥布林低级魔法",
        "requirement": "至少5名哥布林萨满",
        "base_research_time_days": 60,
        "acceleration_rule": "每额外增加1名哥布林萨满，研究时间减少5天（最低至10天）。",
        "cost": {
          "材料": 500,
          "特殊物品": 20
        },
        "effect": "解锁中级魔法的施放权限，如‘大火球’、‘闪光术’、‘恢复术’、‘大型水球’、‘触手召唤’、‘初级精神控制’。显著增强族群的战术多样性。"
      },
      {
        "tier": 3,
        "name": "哥布林高级魔法",
        "prerequisite": "哥布林中级魔法",
        "requirement": "至少15名哥布林萨满",
        "base_research_time_days": 120,
        "acceleration_rule": "每额外增加1名哥布林萨满，研究时间减少5天（最低至30天）。",
        "cost": {
          "材料": 2000,
          "特殊物品": 50
        },
        "effect": "解锁强大的高级魔法，如‘连锁闪电’、‘区域火灾’、‘小型水灾’，以及特殊的‘恶堕’仪式。使族群具备改变局部战局的决定性力量。"
      }
    ],
    "special_technology_details": {
      "name": "恶堕",
      "summary": "一项高级魔法仪式，通过改造雌性的身体与灵魂，使其在保持原有性格与习惯的基础上，完全忠诚于哥布林族群。",
      "execution": "由哥布林萨满主持，对目标雌性进行一次性的、不可逆的身体改造。",
      "effects": [
        {
          "type": "忠诚度",
          "description": "雌性将完全服从并忠诚于哥布林王及其族群，视巢穴为自己的家。"
        },
        {
          "type": "身体改造",
          "description": "身体结构被优化，变得更具魅力，对性刺激的反应更强烈，快感感知增强。"
        },
        {
          "type": "繁殖力提升",
          "description": "受孕率提升，每次生产的后代数量额外增加20%。"
        },
