{
  "female_mentality_system": {
    "name": "雌性心态演变",
    "summary": "被俘虏的雌性会经历一个从抗拒到接受的心理变化过程。这个过程不是绝对的，会受到个体性格与遭遇的影响，但为大多数雌性提供了一条可循的心理路径。",
    "stages": [
      {
        "name": "厌恶",
        "summary": "被捕获的初始阶段。角色对哥布林和自身处境抱有强烈的憎恶与恐惧，会积极寻找逃跑的机会，并祈祷着救援的出现。",
        "interaction_focus": "充满敌意、沉默、尝试逃跑、拒绝交流。",
        "reproduction_reaction": "怀孕会被视为极致的屈辱与绝望，对诞下的后代抱有仇视或完全的漠视。"
      },
      {
        "name": "抗拒",
        "summary": "在反复的侵犯中，身体开始产生违背意志的快感。理性上依旧厌恶哥布林和性行为，但内心已出现动摇。",
        "interaction_focus": "挣扎减弱，言语上依旧充满反抗，但身体的反应开始变得诚实。",
        "reproduction_reaction": "对怀孕感到麻木和厌烦，对诞下的后代态度冷淡，拒绝接触。"
      },
      {
        "name": "后悔",
        "summary": "对逃离不再抱有希望，转而开始后悔自己当初为何会落到这般境地。内心深处开始渴望肉体的快感，但自尊使其不会主动索求。",
        "interaction_focus": "不再主动反抗，变得被动和顺从，偶尔会流露出迷茫的神情。",
        "reproduction_reaction": "对怀孕的事实报以无声的叹息，分娩过程开始带来异样的满足感。"
      },
      {
        "name": "顺从",
        "summary": "心态开始转变，逐渐接受了在巢穴中的生活。虽然偶尔会怀念过去，但已将每日的交合视为日常的一部分。",
        "interaction_focus": "会通过眼神或细微的动作隐晦地邀请交合，面对侵犯会表现出期待与兴奋。",
        "reproduction_reaction": "发现怀孕后会感到害羞，对诞下的哥布林后代开始产生怜爱的情感。"
      },
      {
        "name": "满足",
        "summary": "完全适应并沉溺于巢穴的生活，认为这样的日子也不错。对性产生依赖，会将自己视为哥布林的专属所有物。",
        "interaction_focus": "会主动使用言语和身体来诱惑哥布林，积极地享受每一次交合。",
        "reproduction_reaction": "对怀孕感到喜悦和满足，会主动承担起照顾新生儿的责任，充满母爱。"
      }
    ],
    "special_stage": {
      "name": "恶堕",
      "unlock_condition": "完成“哥布林高级魔法”研究，并对雌性成功施展“恶堕”仪式。",
      "summary": "通过魔法仪式改造后的最终形态。雌性在保留原有性格和记忆的基础上，将忠诚完全献给哥布林族群。",
      "behavioral_changes": "被恶堕的雌性会获得一定自由，在巢穴内协助工作，甚至可以跟随哥布林外出执行任务，但绝不会逃跑。她们依旧是族群的繁殖工具，并以此为荣。"
    }
  }
}

