{
  "offense_system": {
    "name": "掠夺与征服",
    "summary": "由哥布林王主动发起，旨在获取资源、俘虏和领土的外部行动。这是驱动巢穴发展与扩张的核心引擎。",
    "actions": [
      {
        "name": "探索",
        "description": "派遣哥布林小队前往未知区域，以发现新的掠夺目标，如商队、村庄、城镇。地图初始被迷雾覆盖。",
        "mechanic": "探索成功率与小队的平均智力相关。"
      },
      {
        "name": "掠夺",
        "description": "对已发现的目标发起一次性的突袭，抢夺资源。行动会遭遇目标的反抗。",
        "mechanic": "掠夺的成败与战利品数量由我方总战力与敌方总战力的对比决定。",
        "outcome": "成功则获得一定数量的‘材料’、小概率获得‘特殊物品’或‘礼物’。失败则会损失参与行动的哥布林。"
      },
      {
        "name": "征服",
        "description": "旨在完全占领一个地点（如村庄）。征服成功后，可选择两种处理方式。",
        "options": [
          {
            "name": "屠杀",
            "effect": "杀死该地点的所有居民，一次性获得大量‘材料’和少量‘特殊物品’。此举会根据死亡人数大幅提升‘知名度’。"
          },
          {
            "name": "臣服",
            "effect": "迫使该地点的居民投降，使其成为巢穴的附属领地。此举会少量提升‘知名度’。"
          }
        ]
      }
    ],
    "subjugation_system": {
      "name": "附属领地管理",
      "summary": "针对已臣服村庄的管理系统。",
      "mechanic": {
        "name": "忠诚度",
        "range": "0-100",
        "initial_value": 50,
        "description": "衡量附属领地对巢穴的服从程度。当忠诚度降至0以下，该领地会立即叛变，并使巢穴的‘知名度’大幅飙升。",
        "modifiers": [
          {
            "action": "给予‘材料’或‘特殊物品’",
            "effect": "小幅提升忠诚度（每次+1至+5）。"
          },
          {
            "action": "赠送‘礼物’",
            "effect": "中幅提升忠诚度（每次+5至+10）。"
          },
          {
            "action": "允许村民享用俘虏的雌性",
            "effect": "大幅提升忠诚度（每次+10至+30）。"
          },
          {
            "action": "巢穴掠夺失败",
            "effect": "降低所有附属领地的忠诚度（每次-1至-5）。"
          },
          {
            "action": "掠夺该附属领地",
            "effect": "巨幅降低其忠诚度（每次-20至-40）。"
          }
        ]
      },
      "output": {
        "name": "定期上贡",
        "description": "忠诚度高于50的附属领地，会在每个回合自动向巢穴提供一定数量的资源。",
        "items": "主要是‘材料’，偶尔会包含‘特殊物品’或‘礼物’。"
      }
    }
  }
}

