每次输出结束必须改进并输出该状态栏：
```
html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>巢穴状态栏</title>
    <style>
        body {
            background-color: white;
            font-family: sans-serif;
            line-height: 1.6;
            color: #333;
        }
        #main-container {
            max-width: 800px;
            margin: 20px auto;
            padding: 15px;
            border: 1px solid #ddd;
            border-radius: 8px;
            background-color: #f9f9f9;
        }
        h1 {
            text-align: center;
            border-bottom: 2px solid #ccc;
            padding-bottom: 10px;
            margin-bottom: 20px;
        }
        h2 {
            border-bottom: 1px solid #eee;
            padding-bottom: 8px;
            margin-top: 25px;
            color: #444;
        }
        /* 优化details/summary样式，使其更像一个可交互的面板 */
        details {
            border: 1px solid #ddd;
            border-radius: 4px;
            margin-bottom: 15px;
            background-color: #fff;
        }
        summary {
            font-weight: bold;
            padding: 12px;
            background-color: #f1f1f1;
            cursor: pointer;
            outline: none; /* 移除点击时的焦点框 */
        }
        details[open] > summary {
            border-bottom: 1px solid #ddd;
        }
        /* 面板内容区域的样式 */
        .panel-content {
            padding: 15px;
            border-top: 1px solid #ddd;
        }
        ul {
            padding-left: 20px;
            list-style-type: '✧ ';
        }
        li {
            margin-bottom: 5px;
        }
        strong {
            color: #111;
        }
        hr {
            border: 0;
            border-top: 1px dashed #ccc;
            margin: 15px 0;
        }
        /* 响应式设计：在小屏幕上调整边距和内边距 */
        @media (max-width: 600px) {
            #main-container {
                margin: 10px;
                padding: 10px;
            }
            .panel-content, summary {
                padding: 10px;
            }
        }
    </style>
</head>
<body>

    <div id="main-container">
        <h1>哥布林的巢穴</h1>

        <div id="status-container">

        </div>
    </div>

    <script>
        // 全局状态锁，防止并发更新
        let isUpdating = false;

        /*
         * 核心数据获取函数: STscript
         * 这是一个模拟函数，用于演示。在实际环境中，它会与后端进行通信。
         * 它返回一个Promise，模拟网络延迟。
        */
