<StatusBlock>
<style>
    .goblin-nest-container {
        --main-bg: #1a1816;
        --panel-bg: #2a2623;
        --border-color: #4f463d;
        --text-color: #c9b8a5;
        --title-color: #e6a75a;
        --highlight-color: #d95757;
        --green-highlight: #7aa27a;
        --blue-highlight: #6a8aaa;

        font-family: "Palatino Linotype", "Book Antiqua", Palatino, serif;
        background-color: var(--main-bg);
        border: 2px solid var(--border-color);
        border-radius: 8px;
        padding: 15px;
        margin: 20px auto;
        max-width: 800px;
        box-shadow: 0 5px 15px rgba(0, 0, 0, 0.5);
        background-image: url('https://www.transparenttextures.com/patterns/crissxcross.png');
    }

    .goblin-nest-container details {
        background: var(--panel-bg);
        border: 1px solid var(--border-color);
        border-radius: 5px;
        margin-bottom: 12px;
        box-shadow: inset 0 1px 3px rgba(0,0,0,0.3);
    }

    .goblin-nest-container summary {
        padding: 12px 15px;
        cursor: pointer;
        font-weight: bold;
        color: var(--title-color);
        list-style: none;
        display: flex;
        align-items: center;
        border-bottom: 1px solid var(--border-color);
        transition: background-color 0.2s ease;
        text-shadow: 1px 1px 2px rgba(0,0,0,0.7);
    }
    .goblin-nest-container details[open] > summary {
        border-bottom-color: transparent;
    }
    .goblin-nest-container summary:hover {
        background-color: #38322d;
    }

    .goblin-nest-container summary::-webkit-details-marker {
        display: none;
    }

    .goblin-nest-container summary::before {
        content: '🪓';
        margin-right: 10px;
        font-size: 1.1em;
        filter: sepia(0.3);
    }

    .nest-panel-content {
        padding: 15px;
        line-height: 1.8;
        color: var(--text-color);
        white-space: pre-wrap;
        font-size: 0.95em;
        border-top: 1px solid var(--border-color);
        background-color: rgba(0,0,0,0.1);
    }

    /* Custom icons for each section */
    .goblin-nest-container .summary-king::before { content: '👑'; }
    .goblin-nest-container .summary-nest::before { content: '🏰'; }
    .goblin-nest-container .summary-captives::before { content: '⛓️'; }
    .goblin-nest-container .summary-fallen::before { content: '💖'; }
    .goblin-nest-container .summary-tech::before { content: '📜'; }
    .goblin-nest-container .summary-factions::before { content: '🤝'; }

    /* Styling for different lines within the panels */
    .nest-panel-content strong {
        color: var(--title-color);
        font-weight: normal;
    }
    .nest-panel-content .resource-line strong { color: var(--green-highlight); }
    .nest-panel-content .threat-line strong { color: var(--highlight-color); }
    .nest-panel-content .research-line { color: var(--blue-highlight); }

    /* Specific styling for list-like items */
    .nest-panel-content .list-item {
        display: block;
        margin-top: 8px;
        padding-left: 15px;
        border-left: 2px solid var(--border-color);
    }
    .nest-panel-content .list-item:first-of-type {
        margin-top: 5px;
    }
</style>

<div class="goblin-nest-container">
    <details open>
        <summary class="summary-king">巢穴之主</summary>
        <div class="nest-panel-content">
  姓名: {{user:名字或称号}}
  种族: 哥布林王
  战力: {{战力数值}}
  属性: 生命 {{当前生命值}}/{{生命值上限}} | 体质 {{体质数值}} | 魔力 {{魔力数值}} | 智力 {{智力数值}}
  个人武装: {{你的主武器}}, {{你的护甲}}, {{你的特殊饰品}}
</div>
    </details>
    <details open>
